"""
Provide the creation of collector configuration for gNodeB with classical deployment.
"""
from typing import Any, List
from taf.ul.log_collection.config.builders.protocols.gnb import GnbProtocolsCollectorConfigurator


class ClassicalGnbProtocolsCollectorConfigurator(GnbProtocolsCollectorConfigurator):
    """
    Configuration creation for protocols logs on classical gNodeBs.

    Attributes:
        protocol_capture_details: stores the interfaces and the port numbers on which protocol messages are sent
        interface_groups: groups several protocols by group name in order to create one common collector
                         if protocols packets capturing is on the same interface
    """
    protocol_capture_details: dict = {
        "f1c": {"network_interface": "any", "port": 38472},
        "e1c": {"network_interface": "any", "port": 38462},
        "ngc": {"network_interface": "any", "port": 38412},
        "xnc": {"network_interface": "any", "port": 38422},
        "x2c": {"network_interface": "any", "port": 36422},
    }
    interface_groups: dict = {v: k for k, values in {"centralised_unit": ("f1c", "e1c", "ngc", "xnc", "x2c")}.items() for v in values}

    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self.collector_cfg = []

    def add_protocols(self: Any, ne_log_name: str, ne_log_configuration: dict) -> None:
        """
        Create for all interfaces in provided 'configuration' group collectors configurations
        and append them to the global collector configuration list of the builder.

        :param ne_log_name: The name of the collector given in configuration
        :param ne_log_configuration: protocols specific configuration dictionary,
            requires 'type' and 'interfaces' information,
            e.g:
                configuration = {'type': 'protocols', 'interfaces': 'e1c, f1c'}
        """
        self._verify_configuration(ne_log_configuration)
        collector_members = self._add_collectors(ne_log_configuration)
        collector_configuration = {
            'name': ne_log_name,
            'type': 'group',
            'members': collector_members
        }
        self.collector_cfg.append(collector_configuration)
        while self.collector_cfg:
            self._collector_configuration_data.append(self.collector_cfg.pop())
        # todo: call add_mapping_entry

    def _add_collectors(self, configuration: dict) -> list:
        """
        Create all collectors and append them to the global collector configuration list
        or extend collector configuration options if collector already exists.

        :return: list of added collector names
        """
        collector_members: List[str] = []
        interfaces = self._get_interfaces_from_configuration(configuration)

        for interface in interfaces:
            if self._interface_collector_can_be_merged(interface):
                merged_collector_name = self._merge_collector(interface)
                interface_group = self.interface_groups[interface]
                self._update_group_collector_member_name(collector_members, interface_group, merged_collector_name)
            else:
                collector = self._add_collector(interface)
                collector_members.append(collector)
        return collector_members

    def _add_collector(self: Any, interface: str) -> str:
        interface_group = self.interface_groups[interface]
        collector_configuration = self._create_centralised_unit_collector_configuration(interface_group, interface)
        self.collector_cfg.append(collector_configuration)
        return collector_configuration["name"]

    def _create_centralised_unit_collector_configuration(self: Any, interface_group: str, interface: str) -> dict:
        """
        Create collector configuration for interfaces belongs to 'centralised_unit ' group.
        """
        network_interface, port = self._get_protocol_capture_details(interface)
        collector_configuration = {
            'name': f"{self.ne_type}_{self.ne_id}_{interface_group}_{interface}",
            'type': 'tcpdump',
            'options': f"-i {network_interface} port {port}",
            'executor': self._get_ssh_connection_details_to_gNB(),
            'capture_locally': 'yes'
        }
        return collector_configuration

    def _get_protocol_capture_details(self: Any, interface: str) -> tuple:
        """
        Get the interface and the port for the given protocol interface
        """
        return (
            self.protocol_capture_details[interface]['network_interface'],
            self.protocol_capture_details[interface]['port']
        )

    def _get_ssh_connection_details_to_gNB(self: Any) -> dict:
        """
        Return ssh details to gNB.
        """

        lmp_connection = self.tl_config_information_provider.get_lmp_connection(self.ne_id, self.ne_type)
        proxy_connection = self.tl_config_information_provider.get_test_pc(self.ne_id, self.ne_type)
        proxy = {
            'host': proxy_connection.default_ssh_connection_details.addr,
            'user': proxy_connection.default_ssh_connection_details.username,
            'password': proxy_connection.default_ssh_connection_details.password}
        return {
            'host': lmp_connection.addr,
            'user': lmp_connection.username,
            'password': lmp_connection.password,
            'proxy': proxy}

    def _get_collector_configuration(self: Any, interface: str) -> dict:
        interface_group = self.interface_groups[interface]
        collector_name = f"{self.ne_type}_{self.ne_id}_{interface_group}"
        for collector_cfg in self.collector_cfg:
            if collector_name in collector_cfg["name"]:
                return collector_cfg
        raise Exception(f"{interface} configuration not found")

    def _interface_collector_can_be_merged(self: Any, interface: str) -> bool:
        if interface in self.interface_groups:
            interface_group = self.interface_groups[interface]
            for collector_cfg in self.collector_cfg:
                if f"{self.ne_type}_{self.ne_id}_{interface_group}" in collector_cfg["name"]:
                    return True
        return False

    def _merge_collector(self, interface: str) -> str:
        """"
        Extends collector configurations options
        """
        _, port = self._get_protocol_capture_details(interface)
        collector_configuration = self._get_collector_configuration(interface)
        collector_configuration["name"] += f"_{interface}"
        collector_configuration["options"] += f" or port {port}"
        return collector_configuration["name"]

    def _update_group_collector_member_name(self: Any, collector_members: list, interface_group: str, new_collector_name: str) -> None:
        for index, collector_member in enumerate(collector_members):
            if collector_member.startswith(f"{self.ne_type}_{self.ne_id}_{interface_group}"):
                collector_members[index] = new_collector_name
